import{showToast}from"./utils.js";const MOBILE_QUERY="(max-width: 900px)";function isMobileViewport(){return"undefined"!=typeof window&&"function"==typeof window.matchMedia&&window.matchMedia(MOBILE_QUERY).matches}function getUa(){return(navigator.userAgent||"").toLowerCase()}function isIosMobile(){const n=getUa();return/iphone|ipad|ipod/.test(n)}function isAndroidMobile(){return/android/.test(getUa())}function isStandaloneMode(){return"function"==typeof window.matchMedia&&window.matchMedia("(display-mode: standalone)").matches||!0===window.navigator.standalone}function hideInstallUi(n,t){n.classList.add("hidden"),t.classList.add("hidden"),t.textContent=""}function showIosInstructions(n){n.textContent="iOS: Поделиться -> На экран Домой.",n.classList.remove("hidden")}function shouldSkipInstallUi(n,t,e){return!n||!t&&!e||isStandaloneMode()}function bindInstallEvents(n,t,e){let i=null;n.addEventListener("click",async()=>{if(e)return showIosInstructions(t);if(!i)return void showToast('Откройте меню браузера и выберите "Установить приложение".',"info");i.prompt();const{outcome:o}=await i.userChoice;"accepted"===o&&(hideInstallUi(n,t),showToast("Приложение установлено","success")),i=null}),window.addEventListener("beforeinstallprompt",t=>{t.preventDefault(),i=t,n.classList.remove("hidden")})}function setupOfflineStatusBanner(){const n=document.getElementById("offline-status-banner");if(!n)return;const t=()=>{const t="undefined"!=typeof navigator&&!1===navigator.onLine;n.classList.toggle("hidden",!t),t&&showToast("Вы оффлайн. Часть действий временно недоступна.","info")};t(),window.addEventListener("offline",t),window.addEventListener("online",()=>{n.classList.add("hidden"),showToast("Сеть восстановлена","success")})}export function setupPwaInstall(){const n=document.getElementById("pwa-install-btn"),t=document.getElementById("pwa-install-ios-hint");if(setupOfflineStatusBanner(),!n||!t)return;const e=isMobileViewport(),i=isIosMobile();if(shouldSkipInstallUi(e,i,isAndroidMobile()))return hideInstallUi(n,t);bindInstallEvents(n,t,i),window.addEventListener("appinstalled",()=>hideInstallUi(n,t)),i&&n.classList.remove("hidden")}